package lifeos.md.tapilot.speech

/** Preserve Vibelet's paragraph boundary, including Markdown generated by voice polishing. */
internal fun appendSpeechTranscript(current: String, transcript: String): String {
    val normalized = transcript.trim()
    if (normalized.isEmpty()) return current
    if (current.isEmpty()) return normalized
    return current + (if (current.last().isWhitespace()) "" else "\n") + normalized
}
